CREATE TABLE intelligence_disclosure_receipts(
  id uuid PRIMARY KEY,node_id uuid NOT NULL REFERENCES nodes(id),workspace_id uuid REFERENCES workspaces(id),principal_id uuid NOT NULL REFERENCES principals(id),context_package_id uuid REFERENCES context_packages(id),answer_id uuid REFERENCES answers(id),task_class text NOT NULL CHECK(task_class IN('retrieval','summarization','analysis','coding','multimodal','long_context')),sensitivity text NOT NULL CHECK(sensitivity IN('public','internal','confidential','restricted')),execution_mode text NOT NULL CHECK(execution_mode IN('retrieval_without_generation','generation')),selected_provider text NOT NULL,selected_model text,external_disclosure boolean NOT NULL,disclosed_fragment_count integer NOT NULL DEFAULT 0 CHECK(disclosed_fragment_count>=0),estimated_input_tokens integer NOT NULL DEFAULT 0 CHECK(estimated_input_tokens>=0),estimated_cost_usd numeric(12,6) NOT NULL DEFAULT 0 CHECK(estimated_cost_usd>=0),actual_cost_usd numeric(12,6) CHECK(actual_cost_usd>=0),latency_ms integer CHECK(latency_ms>=0),fallback_chain jsonb NOT NULL DEFAULT '[]',policy_snapshot jsonb NOT NULL,route_reasons jsonb NOT NULL DEFAULT '[]',status text NOT NULL CHECK(status IN('planned','succeeded','failed','retrieval_only')),error_message text,created_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz
);
CREATE INDEX intelligence_receipts_scope_idx ON intelligence_disclosure_receipts(node_id,principal_id,created_at DESC);
CREATE TABLE intelligence_provider_health(node_id uuid NOT NULL REFERENCES nodes(id),provider_id text NOT NULL,healthy boolean NOT NULL,latency_ms integer,error_message text,checked_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(node_id,provider_id));
CREATE TABLE intelligence_budget_ledger(id uuid PRIMARY KEY,node_id uuid NOT NULL REFERENCES nodes(id),principal_id uuid NOT NULL REFERENCES principals(id),receipt_id uuid NOT NULL REFERENCES intelligence_disclosure_receipts(id),provider_id text NOT NULL,amount_usd numeric(12,6) NOT NULL CHECK(amount_usd>=0),occurred_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX intelligence_budget_month_idx ON intelligence_budget_ledger(node_id,principal_id,occurred_at DESC);
